final class SidebarLayout:NSObject,NSSplitViewDelegate {
 func splitView(_ splitView:NSSplitView,shouldAdjustSizeOfSubview view:NSView)->Bool {view !== splitView.subviews.first}
 func splitView(_ splitView:NSSplitView,constrainSplitPosition proposedPosition:CGFloat,ofSubviewAt dividerIndex:Int)->CGFloat {
  if splitView.isVertical {return min(max(proposedPosition,260),380)}
  return min(max(proposedPosition,100),max(100,splitView.bounds.height-310))
 }
 func splitView(_ splitView:NSSplitView,resizeSubviewsWithOldSize oldSize:NSSize){
  guard splitView.subviews.count==2 else{return}
  let first=splitView.subviews[0],second=splitView.subviews[1],size=splitView.bounds.size,gap=splitView.dividerThickness
  if splitView.isVertical {let width=min(max(first.frame.width,260),380);first.frame=NSRect(x:0,y:0,width:width,height:size.height);second.frame=NSRect(x:width+gap,y:0,width:max(0,size.width-width-gap),height:size.height)}
  else if second.isHidden {first.frame=splitView.bounds}
  else {let height=min(max(first.frame.height,100),max(100,size.height-310));first.frame=NSRect(x:0,y:0,width:size.width,height:height);second.frame=NSRect(x:0,y:height+gap,width:size.width,height:max(0,size.height-height-gap))}
 }
}

