 @objc func sftp(){if tabs.selectedTabViewItem?.view is RDPWorkspace {alert("RDP 标签不提供 SFTP，请切换到 SSH 标签。");return};if tabs.selectedTabViewItem?.view is VNCWorkspace {alert("VNC 标签不提供 SFTP，请切换到 SSH 标签。");return};if let ftp=tabs.selectedTabViewItem?.view as? FTPWorkspace{window.makeFirstResponder(ftp.path);return};if activeTerminal?.serialSettings != nil || activeTerminal?.telnetSettings != nil {alert("此会话不提供 SFTP，请切换到 SSH 标签。");return};if let workspace=tabs.selectedTabViewItem?.view as? SSHWorkspace {workspace.toggleFiles();updateFileSidebar();return};guard let s=selected else{alert("先连接一个 SSH 会话，即可浏览远程文件。");return};guard s.connectionKind == .ssh else{alert("请选择 SSH 会话以使用 SFTP。");return};openSSH(s)}

 func updateTabStrip(){for item in tabs.tabViewItems where item !== tabs.selectedTabViewItem{(item.view as? RDPWorkspace)?.releaseInputFocus()};updateFileSidebar();for view in tabStrip.arrangedSubviews {tabStrip.removeArrangedSubview(view);view.removeFromSuperview()};for (index,item) in tabs.tabViewItems.enumerated(){observeConnection(item);let b=WorkspaceTabButton(title:item.label,target:self,action:#selector(selectTab(_:)));b.owner=self;b.tabItem=item;b.isCurrent = item === tabs.selectedTabViewItem;b.menu=tabContextMenu(item);b.tag=index;b.widthAnchor.constraint(equalToConstant:150).isActive=true;b.lineBreakMode = .byTruncatingMiddle;let pane=(item.view as? TerminalPane) ?? (item.view as? SSHWorkspace)?.terminal;if let pane=pane,pane.isLogging || pane.isRecordingInput || pane.isInputSyncSource || pane.isInputSyncTarget {let title=NSMutableAttributedString(string:item.label+(pane.isRecordingInput ? " REC" : pane.isInputSyncSource ? " SYNC→" : pane.isInputSyncTarget ? " ←SYNC" : "  ●"),attributes:[.font:NSFont.systemFont(ofSize:12,weight:.medium),.foregroundColor:item === tabs.selectedTabViewItem ? AppTheme.accent : AppTheme.muted]);title.addAttribute(.foregroundColor,value:(pane.isInputSyncSource || pane.isInputSyncTarget) && !pane.isRecordingInput ? NSColor.systemOrange : NSColor.systemRed,range:NSRange(location:(item.label as NSString).length,length:title.length-(item.label as NSString).length));b.attributedTitle=title};b.toolTip=item.label+(pane?.isRecordingInput == true ? "\n正在录制此标签输入" : "")+(pane?.isInputSyncSource == true ? "\n实时输入同步：来源" : pane?.isInputSyncTarget == true ? "\n实时输入同步：目标" : "")+(pane?.isLogging == true ? "\n正在记录："+(pane?.lastLogURL?.path ?? "") : "");b.baseTooltip=b.toolTip ?? item.label;b.isBordered=false;b.font = .systemFont(ofSize:12,weight:.medium);b.image=AppTheme.symbol((item.view is VNCWorkspace || item.view is RDPWorkspace) ? "desktopcomputer" : item.view is FTPWorkspace ? "folder.badge.gearshape" : pane?.serialSettings != nil ? "cable.