  }else{
   fileHost.isHidden=false
   let placeholder=SidebarPlaceholder(rdp:tabs.selectedTabViewItem?.view is RDPWorkspace,vnc:tabs.selectedTabViewItem?.view is VNCWorkspace,ftp:tabs.selectedTabViewItem?.view is FTPWorkspace,serial:activeTerminal?.serialSettings != nil,telnet:activeTerminal?.telnetSettings != nil);placeholder.translatesAutoresizingMaskIntoConstraints=false;fileHost.addSubview(placeholder);NSLayoutConstraint.activate([placeholder.leadingAnchor.constraint(equalTo:fileHost.leadingAnchor),placeholder.trailingAnchor.constraint(equalTo:fileHost.trailingAnchor),placeholder.topAnchor.constraint(equalTo:fileHost.topAnchor),placeholder.bottomAnchor.constraint(equalTo:fileHost.bottomAnchor)])
