 @objc func selectTab(_ sender:NSButton){if let button=sender as? WorkspaceTabButton,let item=button.tabItem {guard tabs.indexOfTabViewItem(item) != NSNotFound else{return};tabs.selectTabViewItem(item)}else{guard tabs.tabViewItems.indices.contains(sender.tag) else{return};tabs.selectTabViewItem(at:sender.tag)};updateTabStrip();activeTerminal?.web.evaluateJavaScript("focusTerminal()",completionHandler:nil);(tabs.selectedTabViewItem?.view as? VNCWorkspace)?.focusDesktop();(tabs.selectedTabViewItem?.view as? RDPWorkspace)?.focusDesktop()}
