 @objc func quickConnect(){do {if quick.stringValue.trimmingCharacters(in:.whitespacesAndNewlines).hasPrefix("rdp://"){openRDP(try Session.quickRDP(quick.stringValue.trimmingCharacters(in:.whitespacesAndNewlines)))}else if quick.stringValue.trimmingCharacters(in:.whitespacesAndNewlines).hasPrefix("vnc://"){openVNC(try Session.quickVNC(quick.stringValue.trimmingCharacters(in:.whitespacesAndNewlines)))}else if quick.stringValue.trimmingCharacters(in:.whitespacesAndNewlines).hasPrefix("telnet://"){openTelnet(try TelnetSettings.quickSession(quick.stringValue))}else{openSSH(try QuickConnection.parse(quick.stringValue))}}catch{alert(error.localizedDescription)}}
 func openSSH(_ input:Session){guard input.connectionKind == .ssh else{alert("请选择 SSH 会话");return};do {_ = try input.validated()}catch{alert(error.localizedDescription);return};let session=recordRecent(input);let socket=NSTemporaryDirectory()+"mt-"+UUID().uuidString.replacingOccurrences(of:"-",with:"").prefix(16);let item=NSTabViewItem(identifier:UUID().uuidString);item.label=session.name;item.view=SSHWorkspace(session:session,args:arguments(session,sftp:false),socket:String(socket),preferences:savedTerminalPreferences);if let workspace=item.view as? SSHWorkspace {watchLogging(workspace.terminal)};tabs.addTabViewItem(item);tabs.selectTabViewItem(item);updateTabStrip()}
 @objc func closeTab(){guard NSApp.keyWindow === window else{NSApp.keyWindow?.performClose(nil);return};if let item=tabs.selectedTabViewItem {if let workspace=item.view as? SSHWorkspace,!workspace.confirmEditorClose(){return};if let workspace=item.view as? FTPWorkspace,!workspace.confirmEditorClose(){return};(item.view as? TerminalPane)?.stop();(item.view as? SSHWorkspace)?.stop();(item.view as? FTPWorkspace)?.stop();(item.view as? VNCWorkspace)?.stop();(item.view as? RDPWorkspace)?.stop();tabs.removeTabViewItem(item);updateTabStrip()}}
 func applicationShouldTerminate(_ sender:NSApplication)->NSApplication.TerminateReply {if let macro=macroWindow,!macro.confirmDiscard(){return .terminateCancel};for item in tabs.tabViewItems {if let workspace=item.view as? SSHWorkspace,!workspace.confirmEditorClose(){return .terminateCancel};if let workspace=item.view as? FTPWorkspace,!workspace.confirmEditorClose(){return .terminateCancel}};if !tabs.tabViewItems.isEmpty {let a=NSAlert();a.messageText="退出并关闭所有会话？";a.addButton(withTitle:"退出");a.addButton(withTitle:"取消");if a.runModal() != .alertFirstButtonReturn {return .terminateCancel}};macroWindow?.playback.cancel();broadcastWindow?.runner.cancel();inputSyncWindow?.stopSynchronization();for item in tabs.tabViewItems {(item.view as? TerminalPane)?.stop();(item.view as? SSHWorkspace)?.stop();(item.view as? FTPWorkspace)?.stop();(item.view as? VNCWorkspace)?.stop();(item.view as? RDPWorkspace)?.stop()};if !TerminalLogWriter.isDrained {TerminalLogWriter.afterDraining{NSApp.reply(toApplicationShouldTerminate:true)};return .terminateLater};return .terminateNow}
